@layer moduix.components {
  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-height: var(--moduix-tooltip-trigger-height, var(--moduix-size-md));
    margin: 0;
    padding: var(--moduix-tooltip-trigger-padding-y, var(--moduix-spacing-1))
      var(--moduix-tooltip-trigger-padding-x, var(--moduix-spacing-3-5));
    border: var(--moduix-tooltip-trigger-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-tooltip-trigger-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-tooltip-trigger-radius, var(--moduix-radius-md));
    background-color: var(--moduix-tooltip-trigger-bg, var(--moduix-color-background));
    color: var(--moduix-tooltip-trigger-color, var(--moduix-color-foreground));
    font: inherit;
    font-size: var(--moduix-tooltip-trigger-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-tooltip-trigger-line-height, var(--moduix-line-height-text-sm));
    user-select: none;
    outline: 0;
    cursor: pointer;
    transition:
      background-color var(--moduix-tooltip-transition, var(--moduix-duration-fast))
        var(--moduix-ease-in-out),
      border-color var(--moduix-tooltip-transition, var(--moduix-duration-fast))
        var(--moduix-ease-in-out),
      color var(--moduix-tooltip-transition, var(--moduix-duration-fast)) var(--moduix-ease-in-out);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-tooltip-trigger-bg-hover, var(--moduix-color-accent));
      }
    }

    &:active,
    &[data-state='open'] {
      background-color: var(
        --moduix-tooltip-trigger-bg-active,
        var(--moduix-tooltip-trigger-bg-hover, var(--moduix-color-accent))
      );
    }

    &:focus-visible {
      outline: var(
          --moduix-tooltip-focus-ring-width,
          var(--moduix-focus-ring-inset-width, var(--moduix-border-width-sm))
        )
        solid var(--moduix-tooltip-focus-ring-color, var(--moduix-color-ring));
      outline-offset: var(
        --moduix-tooltip-focus-ring-offset,
        var(--moduix-focus-ring-inset-offset)
      );
    }

    &[data-disabled],
    &[disabled] {
      pointer-events: none;
      opacity: var(--moduix-tooltip-disabled-opacity, var(--moduix-opacity-disabled));
    }
  }

  .disabledTrigger {
    display: inline-flex;
    cursor: not-allowed;

    & > :is(:disabled, [data-disabled]) {
      pointer-events: none;
    }
  }

  .positioner {
    z-index: var(--z-index, var(--moduix-z-popup));
    max-width: var(--available-width);
    outline: 0;
  }

  .content {
    box-sizing: border-box;
    position: relative;
    z-index: var(--moduix-tooltip-z-index, var(--moduix-z-popup));
    max-width: min(var(--moduix-tooltip-max-width, 20rem), var(--available-width));
    max-height: min(var(--moduix-tooltip-max-height, 24rem), var(--available-height, 100dvh));
    overflow: visible;
    padding: var(--moduix-tooltip-padding-y, var(--moduix-spacing-1))
      var(--moduix-tooltip-padding-x, var(--moduix-spacing-2));
    border: var(--moduix-tooltip-border-width, var(--moduix-border-width-sm)) solid
      var(--moduix-tooltip-border-color, var(--moduix-color-border));
    border-radius: var(--moduix-tooltip-radius, var(--moduix-radius-md));
    background-color: var(--moduix-tooltip-bg, var(--moduix-color-popover));
    color: var(--moduix-tooltip-color, var(--moduix-color-popover-foreground));
    box-shadow: var(--moduix-tooltip-shadow, var(--moduix-shadow-md));
    font-size: var(--moduix-tooltip-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-tooltip-line-height, var(--moduix-line-height-text-sm));
    text-align: center;
    overflow-wrap: anywhere;
    transform-origin: var(--transform-origin);

    &[data-state='open'] {
      animation: tooltip-content-in
        var(
          --moduix-tooltip-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-fast))
        )
        var(--moduix-popup-motion-easing, ease-out);
    }

    &[data-state='closed'] {
      animation: tooltip-content-out
        var(
          --moduix-tooltip-transition,
          var(--moduix-popup-motion-duration, var(--moduix-duration-fast))
        )
        var(--moduix-popup-motion-easing, ease-in);
    }

    &[data-instant] {
      animation-duration: 0s;
    }
  }

  .arrow {
    --arrow-background: var(
      --moduix-tooltip-arrow-background,
      var(--moduix-tooltip-bg, var(--moduix-color-popover))
    );
    --arrow-size: var(--moduix-tooltip-arrow-size, var(--moduix-spacing-2-5));
  }

  .arrowTip {
    border-top: var(--moduix-tooltip-border-width, var(--moduix-border-width-sm)) solid
      var(
        --moduix-tooltip-arrow-stroke-color,
        var(--moduix-tooltip-border-color, var(--moduix-color-border))
      );
    border-left: var(--moduix-tooltip-border-width, var(--moduix-border-width-sm)) solid
      var(
        --moduix-tooltip-arrow-stroke-color,
        var(--moduix-tooltip-border-color, var(--moduix-color-border))
      );
  }

  @media (prefers-reduced-motion: reduce) {
    .trigger {
      transition: none;
    }

    .content[data-state] {
      animation: none;
    }
  }

  @keyframes tooltip-content-in {
    from {
      opacity: var(
        --moduix-tooltip-popup-starting-opacity,
        var(--moduix-popup-motion-starting-opacity, 0)
      );
      translate: var(
          --moduix-tooltip-popup-starting-translate-x,
          var(--moduix-popup-motion-starting-translate-x, 0)
        )
        var(
          --moduix-tooltip-popup-starting-translate-y,
          var(--moduix-popup-motion-starting-translate-y, 0)
        );
      transform: scale(
        var(
          --moduix-tooltip-popup-starting-scale,
          var(--moduix-popup-motion-starting-scale, var(--moduix-scale-popup))
        )
      );
    }

    to {
      opacity: 1;
      translate: 0 0;
      transform: scale(1);
    }
  }

  @keyframes tooltip-content-out {
    from {
      opacity: 1;
      translate: 0 0;
      transform: scale(1);
    }

    to {
      opacity: var(
        --moduix-tooltip-popup-ending-opacity,
        var(--moduix-popup-motion-ending-opacity, 0)
      );
      translate: var(
          --moduix-tooltip-popup-ending-translate-x,
          var(--moduix-popup-motion-ending-translate-x, 0)
        )
        var(
          --moduix-tooltip-popup-ending-translate-y,
          var(--moduix-popup-motion-ending-translate-y, 0)
        );
      transform: scale(
        var(
          --moduix-tooltip-popup-ending-scale,
          var(--moduix-popup-motion-ending-scale, var(--moduix-scale-popup))
        )
      );
    }
  }
}

import { TooltipContext, useTooltip, useTooltipContext } from '@ark-ui/vue/tooltip';
import Tooltip from './Tooltip.vue';
import TooltipArrow from './TooltipArrow.vue';
import TooltipArrowTip from './TooltipArrowTip.vue';
import TooltipBody from './TooltipBody.vue';
import TooltipContent from './TooltipContent.vue';
import TooltipDisabledTrigger from './TooltipDisabledTrigger.vue';
import TooltipPositioner from './TooltipPositioner.vue';
import TooltipRootProvider from './TooltipRootProvider.vue';
import TooltipTrigger from './TooltipTrigger.vue';

export {
  Tooltip,
  TooltipArrow,
  TooltipArrowTip,
  TooltipBody,
  TooltipContext,
  TooltipContent,
  TooltipDisabledTrigger,
  TooltipPositioner,
  TooltipRootProvider,
  TooltipTrigger,
  useTooltip,
  useTooltipContext,
};

export type {
  TooltipArrowProps,
  TooltipArrowTipProps,
  TooltipContentProps,
  TooltipContextProps,
  TooltipOpenChangeDetails,
  TooltipPositionerProps,
  TooltipRootEmits,
  TooltipRootProviderEmits,
  TooltipTriggerProps,
  TooltipTriggerValueChangeDetails,
  UseTooltipContext,
  UseTooltipProps,
  UseTooltipReturn,
} from '@ark-ui/vue/tooltip';

export type { Props as TooltipRootProps } from './Tooltip.vue';
export type { Props as TooltipRootProviderProps } from './TooltipRootProvider.vue';
